import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native spring and interpolate for text pop-up

const { fontFamily: interFamily } = loadInter();



export type PopUpTextProps = Record<string, any>;

const PopUpText: React.FC<PopUpTextProps> = ({
  text = "$,$$$,$$$",
  textColor = "#ffffff",
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const characters = text.split("");

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "nowrap",
          justifyContent: "center",
          maxWidth: width * 0.9,
        }}
      >
        {characters.map((char, index) => {
          const charEntranceFrame = 5 + index * 2;
          const relativeFrame = frame - charEntranceFrame;

          const scale = spring({
            fps,
            frame: relativeFrame,
            config: {
              damping: 12,
              stiffness: 180,
              mass: 0.8,
            },
          });

          // Elements must be completely hidden before their entrance frame
          const opacity = interpolate(relativeFrame, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Animate position up as it enters
          const entranceY = interpolate(relativeFrame, [0, 12], [50 * s, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Continuous gentle floating wave effect after entering
          const idleY = relativeFrame > 0 ? Math.sin(relativeFrame / 12 + index * 0.4) * 8 * s : 0;
          const translateY = entranceY + idleY;

          return (
            <span
              key={index}
              style={{
                fontFamily: interFamily,
                fontWeight: 900,
                fontSize: 120 * s,
                color: textColor,
                lineHeight: 1.1,
                transform: `scale(${scale}) translateY(${translateY}px)`,
                opacity: opacity,
                display: "inline-block",
                transition: "none",
                whiteSpace: char === " " ? "pre" : "normal",
                letterSpacing: -2 * s, // Tighter kerning to match the bold impact style
              }}
            >
              {char}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default PopUpText;